import { claimProject } from "@/lib/metrics";
import Project from "@/models/Project";
import Activity from "@/models/Activity";
import SetupCredential from "@/models/SetupCredential";
import PendingOAS from "@/models/PendingOAS";
import PendingSettings from "@/models/PendingSettings";
import KeyRegistration from "@/models/KeyRegistration";
import User from "@/models/User";
import type { SetupAgent, SetupSource } from "@/lib/setupProvenance";
import {
  OAS_SYNC_ACTIVITY,
  oasProjectFields,
  vectorizeOasChunks,
} from "@/lib/oasSync";
import {
  regenerateGettingStarted,
  refreshHeroTextForOas,
  refreshSuggestedQuestionsForOas,
} from "@/lib/api/services/content";
import { publishPortalOrigin } from "@/lib/portalOrigin";
import { recordCliSignupSource } from "@/lib/attribution.server";
import { projectAccess } from "@/lib/projectAccess";
import { postSignupNotice } from "@/lib/waitlist";

export type ClaimResult =
  | { ok: true; slug: string }
  | { ok: false; reason: "expired" | "already_claimed" | "failed" };

/** The claim itself, independent of how the user authenticated: mark claimed on metrics, attach the
 *  staged spec and settings, create the Project, log, vectorize. Callers own transport concerns. */
export async function completeProjectClaim({
  projectId,
  setupKeyHash,
  userId,
  userEmail,
}: {
  projectId: string;
  setupKeyHash: string;
  userId: string;
  userEmail: string;
}): Promise<ClaimResult> {
  // Claim the project in metrics
  try {
    await claimProject(projectId, setupKeyHash);
  } catch (err) {
    const message = err instanceof Error ? err.message : "Claim failed";
    console.warn(`[claim] metrics refused project_id=${projectId}: ${message}`);
    if (message.includes("410")) return { ok: false, reason: "expired" };
    if (message.includes("409")) return { ok: false, reason: "already_claimed" };
    return { ok: false, reason: "failed" };
  }

  // Pull any artifacts uploaded before claim. Each one is gated on
  // the same setupKeyHash, so a CLI that didn't know the secret
  // can't have written here, and a stale row from another setup
  // attempt won't accidentally attach.
  console.log("[claim] Looking for PendingOAS with projectId:", projectId);
  const [pendingOas, pendingSettings] = await Promise.all([
    PendingOAS.findOneAndDelete({ projectId, setupKeyHash }),
    PendingSettings.findOneAndDelete({ projectId, setupKeyHash }),
    // Once the project is claimed, the setupKey is exhausted - revoke
    // the local credential so the CLI can no longer authenticate
    // against /api/logs/poll. The TTL index would reap it eventually
    // anyway; this just shortens the window.
    SetupCredential.deleteOne({ projectId }),
  ]);
  console.log("[claim] Found pending OAS:", !!pendingOas, "settings:", !!pendingSettings);
  const oas = pendingOas?.oas;
  const settings = pendingSettings?.settings;
  // Reuse the PendingSettings row's createdAt as the "last synced"
  // stamp - that's when the CLI uploaded it, which is the truth we
  // want surfaced as "settings last synced X ago" in the UI.
  const settingsSyncedAt = pendingSettings?.createdAt;
  // One stamp for both halves of the spec write: it goes onto the
  // document with the spec, and `vectorizeOasChunks` filters on it so
  // the vectors it computes can only land on the spec they came from.
  const oasSyncedAt = new Date();

  // Carry setup provenance (CLI or agent-invoked, and which agent) onto the
  // project. It lives on the durable KeyRegistration row rather than any of
  // the staging rows above, so it's still there to copy - but a project can
  // be claimed without one (a registration from before we recorded this, or
  // a project that never came from the CLI), hence the optional read.
  const registration = (await KeyRegistration.findOne(
    { projectId },
    "setupSource setupAgent setupEmail signup_source createdAt",
  ).lean()) as {
    setupSource?: SetupSource;
    setupAgent?: SetupAgent;
    setupEmail?: string;
    signup_source?: string;
    createdAt?: Date;
  } | null;

  // A ReadMe customer's uplift covers everything they OWN, so a project made
  // after they claimed has to carry it from birth. Nothing else reaches it
  // until somebody opens its billing page.
  const owner = await User.findById(userId, "readmeCustomer").lean<{
    readmeCustomer?: unknown;
  }>();

  // Create the project in MongoDB
  const slug = `project-${projectId.split("-")[0]}`;
  const project = await Project.create({
    slug,
    name: oas?.info?.title || "My API",
    metricsId: projectId,
    userId,
    ...(owner?.readmeCustomer
      ? { subscription: { readmeUplift: true } }
      : {}),
    ...(registration?.setupSource ? { setupSource: registration.setupSource } : {}),
    ...(registration?.setupAgent ? { setupAgent: registration.setupAgent } : {}),
    ...(registration?.setupEmail ? { setupEmail: registration.setupEmail } : {}),
    ...(oas ? oasProjectFields(oas, oasSyncedAt) : {}),
    ...(settings ? { settings, settingsSyncedAt } : {}),
  });

  // The slug exists from here on, so the project has a portal origin. Publish
  // it now or the SDK has none until the owner touches their domain settings.
  await publishPortalOrigin(projectId, { slug });

  // Log the activity
  const activities = [
    { project: project._id, action: "Project created", actor: userEmail },
  ];
  if (oas) {
    activities.push({ project: project._id, action: OAS_SYNC_ACTIVITY, actor: userEmail });
  }
  if (settings) {
    activities.push({ project: project._id, action: "Settings synced from CLI", actor: userEmail });
  }
  await Activity.insertMany(activities);

  await recordCliSignupSource({
    userId,
    signupSource: registration?.signup_source,
    registeredAt: registration?.createdAt,
  });

  // Vectorize the OAS so the chat can retrieve a thin slice instead
  // of dumping the whole spec into every prompt. Internal operations
  // are excluded by the chunker - they never get an embedding.
  // Failures are non-fatal and handled inside the helper: without
  // chunks the answer pipeline falls back to the full filtered OAS,
  // which still works (just costs more tokens). Shared with the
  // post-claim re-sync route so both produce identical chunk records.
  if (oas) {
    await vectorizeOasChunks({
      projectObjectId: project._id,
      oas,
      syncedAt: oasSyncedAt,
    });

    // Build the Getting Started capability overview from the fresh spec so the
    // public docs open with it ready. Best-effort (never throws) and degrades
    // to the deterministic grouping when AI isn't configured.
    await regenerateGettingStarted(project._id);
    // Same first-good-OAS moment: seed the landing hero copy + rotating
    // questions from the spec. Both best-effort (never throw).
    await refreshHeroTextForOas(project._id);
    await refreshSuggestedQuestionsForOas(project._id);
  }

  return { ok: true, slug };
}

/** A first project means a signup; its SetupToken is already the record, so this only pings Slack.
 *  Best-effort: a hiccup must never break the claim. */
export async function announceIfFirstProject(userId: string, email: string): Promise<void> {
  try {
    const projectCount = await Project.countDocuments(projectAccess(userId));
    if (projectCount === 1) {
      await postSignupNotice({ email: email.toLowerCase(), source: "claim" });
    }
  } catch (err) {
    console.error("[claim] signup notice failed:", err instanceof Error ? err.message : err);
  }
}
import crypto from "crypto";
import { NextRequest, NextResponse } from "next/server";
import { registerProject } from "@/lib/metrics";
import dbConnect from "@/lib/mongoose";
import SetupCredential from "@/models/SetupCredential";
import KeyRegistration from "@/models/KeyRegistration";
import Project from "@/models/Project";
import {
  parseSetupAgent,
  parseSetupSource,
  type SetupAgent,
  type SetupSource,
} from "@/lib/setupProvenance";
import { parseSetupEmail } from "@/lib/setupProgress";
import { firstIp, hashIp } from "@/lib/agentAccess";
import { deriveSignupSource, parseRef } from "@/lib/attribution";

const SETUP_KEY_TTL_HOURS = 6;

function mintSetupCredential() {
  const setupKey = crypto.randomBytes(32).toString("hex");
  const setupKeyHash = crypto.createHash("sha256").update(setupKey).digest("hex");
  const expiresDate = new Date(Date.now() + SETUP_KEY_TTL_HOURS * 60 * 60 * 1000);
  const setupKeyExpiresAt = expiresDate
    .toISOString()
    .replace("T", " ")
    .replace(/\.\d{3}Z$/, "");
  return { setupKey, setupKeyHash, expiresDate, setupKeyExpiresAt };
}

/**
 * Hand back the registration's existing project with a fresh setup key.
 * The metrics projects table replaces rows per project_id, so re-registering
 * refreshes the setup-key hash instead of duplicating the key mapping, and
 * the Mongo credential mirror is upserted to match (projectId is unique
 * there, so a stale credential gets replaced, not duplicated).
 */
async function reuseRegistration(
  registration: {
    projectId: string;
    setupSource?: SetupSource;
    setupAgent?: SetupAgent;
    signup_source?: string;
  },
  writeKeyHash: string,
  provenance: {
    setupSource?: SetupSource;
    setupAgent?: SetupAgent;
    setupEmail?: string;
    signup_source?: string;
  },
) {
  const fresh = mintSetupCredential();
  await registerProject(registration.projectId, {
    writeKeyHash,
    setupKeyHash: fresh.setupKeyHash,
    setupKeyExpiresAt: fresh.setupKeyExpiresAt,
  });
  await SetupCredential.findOneAndUpdate(
    { projectId: registration.projectId },
    { setupKeyHash: fresh.setupKeyHash, expiresAt: fresh.expiresDate },
    { upsert: true },
  );
  // Backfill provenance, never overwrite it (CLAUDE.md "Setup provenance"). Email is the exception: it is
  // a contact lead, so the freshest value wins whenever one is present.
  const backfill: {
    setupSource?: SetupSource;
    setupAgent?: SetupAgent;
    setupEmail?: string;
    signup_source?: string;
  } = {};
  if (!registration.setupSource && provenance.setupSource) {
    backfill.setupSource = provenance.setupSource;
  }
  if (!registration.setupAgent && provenance.setupAgent) {
    backfill.setupAgent = provenance.setupAgent;
  }
  if (!registration.signup_source && provenance.signup_source) {
    backfill.signup_source = provenance.signup_source;
  }
  if (provenance.setupEmail) {
    backfill.setupEmail = provenance.setupEmail;
  }
  if (Object.keys(backfill).length) {
    await KeyRegistration.updateOne(
      { projectId: registration.projectId },
      { $set: backfill },
    );
  }
  return NextResponse.json(
    {
      project_id: registration.projectId,
      setup_key: fresh.setupKey,
      reused: true,
    },
    { status: 200 },
  );
}

// Best-effort per-IP throttle so an anonymous caller can't mint unbounded
// projects + metrics registrations by spraying fresh write-key hashes. This
// endpoint is unauthenticated by design (setup runs before a session exists),
// and it is idempotent per write-key hash, but a flood of random hashes still
// creates rows and metrics-server registrations. In-process (per serverless
// instance): a cost cap, not a hard quota, same idea as the public-log
// limiter. Override with PROJECT_INIT_RATELIMIT.
const INIT_LIMIT = Number(process.env.PROJECT_INIT_RATELIMIT || "20");
const INIT_WINDOW_MS = 60 * 60 * 1000; // 1 hour
const initHits = new Map<string, { count: number; resetAt: number }>();

function initRateLimited(req: NextRequest): boolean {
  const ip = firstIp(req);
  const key = ip ? hashIp(ip) : "noip";
  const now = Date.now();
  let bucket = initHits.get(key);
  if (!bucket || bucket.resetAt <= now) {
    // Guard the map against unbounded growth from a distinct-key flood.
    if (initHits.size > 10_000) initHits.clear();
    bucket = { count: 0, resetAt: now + INIT_WINDOW_MS };
    initHits.set(key, bucket);
  }
  bucket.count += 1;
  return bucket.count > INIT_LIMIT;
}

/** Test-only: clear the in-process init throttle between cases. */
export function __resetInitRateLimit(): void {
  initHits.clear();
}

export async function POST(req: NextRequest) {
  if (initRateLimited(req)) {
    return NextResponse.json(
      { error: "Too many setup attempts. Please try again later." },
      { status: 429, headers: { "Retry-After": "3600" } },
    );
  }

  let body: {
    write_key_hash?: string;
    email?: unknown;
    setup_source?: unknown;
    setup_agent?: unknown;
    ref?: unknown;
  };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const { write_key_hash } = body;

  // How the CLI says this setup was driven, plus the contact email it
  // captured. Every field is narrowed to something storable and none is ever
  // a reason to reject the request: an older CLI sends none of them, a newer
  // one may name an agent this deploy hasn't heard of, and the email is an
  // optional unverified lead. A malformed value is simply dropped.
  const provenance = {
    setupSource: parseSetupSource(body.setup_source),
    setupAgent: parseSetupAgent(body.setup_agent),
    setupEmail: parseSetupEmail(body.email),
    signup_source: deriveSignupSource({ ref: parseRef(body.ref) }),
  };

  if (!write_key_hash || !/^[0-9a-f]{64}$/i.test(write_key_hash)) {
    return NextResponse.json(
      { error: "write_key_hash must be a SHA-256 hex digest" },
      { status: 400 },
    );
  }
  const writeKeyHash = write_key_hash.toLowerCase();

  await dbConnect();

  // Idempotency: one write key maps to one project, forever. Minting a
  // second project for a known key is never right - ingest resolves the
  // key with `WHERE write_key_hash = ? LIMIT 1`, so a duplicated mapping
  // sends the key's uploads to one project while the CLI watches the
  // other, with no client-side way to reconcile.
  const existing = await KeyRegistration.findOne({ writeKeyHash });
  if (existing) {
    const claimed = await Project.findOne({ metricsId: existing.projectId })
      .select({ _id: 1 })
      .lean();
    if (claimed) {
      return NextResponse.json(
        {
          error: "key_claimed",
          message:
            "This write key already belongs to a claimed project. Remove RESTLESS_KEY from .env and re-run setup to mint a fresh key.",
        },
        { status: 409 },
      );
    }
    return reuseRegistration(existing, writeKeyHash, provenance);
  }

  // Reserve the mapping BEFORE registering with metrics: the unique index
  // on writeKeyHash arbitrates concurrent inits for the same key, so the
  // metrics table can never end up with two projects for one hash. The
  // loser of a race re-reads and takes the reuse path above.
  const projectId = crypto.randomUUID();
  try {
    await KeyRegistration.create({ writeKeyHash, projectId, ...provenance });
  } catch (err: unknown) {
    const isDuplicate =
      typeof err === "object" && err !== null && (err as { code?: number }).code === 11000;
    if (!isDuplicate) throw err;
    const winner = await KeyRegistration.findOne({ writeKeyHash });
    if (winner) return reuseRegistration(winner, writeKeyHash, provenance);
    throw err;
  }

  const fresh = mintSetupCredential();
  try {
    await registerProject(projectId, {
      writeKeyHash,
      setupKeyHash: fresh.setupKeyHash,
      setupKeyExpiresAt: fresh.setupKeyExpiresAt,
    });
  } catch (err) {
    // The reservation must not outlive a failed registration - a dangling
    // row would make every future init for this key "reuse" a project the
    // metrics server never heard of.
    await KeyRegistration.deleteOne({ writeKeyHash, projectId }).catch(() => {});
    throw err;
  }

  // Mirror the hash + expiry to Mongo so unauthenticated CLI helpers
  // like /api/logs/poll can verify the setupKey without round-tripping
  // to the metrics server. The plaintext setupKey is only returned to
  // the caller below; we never persist it on the dashboard side.
  await SetupCredential.create({
    projectId,
    setupKeyHash: fresh.setupKeyHash,
    expiresAt: fresh.expiresDate,
  });

  return NextResponse.json(
    {
      project_id: projectId,
      setup_key: fresh.setupKey,
    },
    { status: 201 },
  );
}
import crypto from "crypto";
import { NextRequest, NextResponse } from "next/server";

import dbConnect from "@/lib/mongoose";
import { announceIfFirstProject, completeProjectClaim } from "@/lib/claimFlow";
import { isAccountScoped } from "@/lib/cliTokenScope";
import { projectAccess } from "@/lib/projectAccess";
import { verifySetupKey } from "@/lib/setupAuth";
import CliAuthToken from "@/models/CliAuthToken";
import Project from "@/models/Project";
import SetupToken from "@/models/SetupToken";

/** Claims for the account `npx restless init` signed in as at its welcome screen: the approved
 *  account-scoped token proves the person, the setup key the project. */
export async function POST(req: NextRequest) {
  let body: { token?: unknown; project_id?: unknown; setup_key?: unknown };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "invalid_json" }, { status: 400 });
  }
  const { token, project_id: projectId, setup_key: setupKey } = body;
  if (typeof token !== "string" || typeof projectId !== "string" || typeof setupKey !== "string") {
    return NextResponse.json({ error: "missing_fields" }, { status: 400 });
  }

  await dbConnect();

  const session = await CliAuthToken.findOne({ token })
    .select({ status: 1, scope: 1, expiresAt: 1, userId: 1, userEmail: 1 })
    .lean<{
      status: string;
      scope?: string;
      expiresAt?: Date;
      userId?: unknown;
      userEmail?: string;
    } | null>();
  // One answer for every way the session is unusable, so the CLI's response is simply "sign in again".
  if (
    !session ||
    session.status !== "authorized" ||
    !isAccountScoped(session) ||
    !session.userId ||
    !session.userEmail ||
    (session.expiresAt && session.expiresAt.getTime() < Date.now())
  ) {
    return NextResponse.json({ error: "session_invalid" }, { status: 401 });
  }
  const userId = String(session.userId);
  const userEmail = session.userEmail;

  // A retry after a lost response finds the key spent and the project already this user's: that's
  // the success it missed, as the browser claim treats it.
  const alreadyOwn = async () => {
    const own = await Project.findOne({ metricsId: projectId, ...projectAccess(userId) }, "slug")
      .lean<{ slug: string } | null>();
    return own
      ? NextResponse.json({ claimed: true, project_slug: own.slug, user_email: userEmail })
      : null;
  };

  // Same possession proof and uniform rejection as /api/agent/identity.
  const proof = await verifySetupKey(projectId, setupKey);
  if (!proof.ok) {
    return (await alreadyOwn()) ?? NextResponse.json({ error: "setup_key_invalid" }, { status: 401 });
  }

  const result = await completeProjectClaim({
    projectId,
    setupKeyHash: proof.setupKeyHash,
    userId,
    userEmail,
  });
  if (!result.ok) {
    if (result.reason === "already_claimed") {
      const owned = await alreadyOwn();
      if (owned) return owned;
    }
    const status =
      result.reason === "expired" ? 410
      : result.reason === "already_claimed" ? 409
      : 502;
    return NextResponse.json({ error: result.reason }, { status });
  }

  // The SetupToken is the CLI-run record /admin/signups lists. Its token is never handed out.
  try {
    await SetupToken.create({
      token: crypto.randomBytes(16).toString("hex"),
      projectId,
      setupKey,
      status: "complete",
      email: userEmail,
      slug: result.slug,
    });
  } catch (err) {
    console.error("[cli-claim] signup record failed:", err instanceof Error ? err.message : err);
  }
  await announceIfFirstProject(userId, userEmail);

  return NextResponse.json({
    claimed: true,
    project_slug: result.slug,
    user_email: userEmail,
  });
}
import mongoose, { Schema, models, type InferSchemaType, type Model } from "mongoose";
import type { NoNull } from "./inferred";

import { SETUP_SOURCES } from "@/lib/setupProvenance";

// Write key hash to metrics project, permanently: what makes `POST /api/projects/init` idempotent, and the
// only row that survives an unclaimed setup. See CLAUDE.md, "Setup provenance" and "Key registry".
const KeyRegistrationSchema = new Schema(
  {
    writeKeyHash: { type: String, required: true, unique: true, index: true },
    projectId: { type: String, required: true, index: true },
    // See src/lib/setupProvenance.ts. Both optional: rows predating this
    // have neither, and a value the wire check rejects is dropped rather
    // than failing the registration. `setupAgent` has no enum on purpose -
    // the CLI can name an agent this deploy has never heard of, and losing
    // that is worse than storing a slug we have no label for.
    setupSource: { type: String, enum: SETUP_SOURCES, default: undefined },
    setupAgent: { type: String, default: undefined },
    // The setup-funnel capture (`src/lib/setupProgress.ts`), here because this is the only record that
    // survives an unclaimed setup. `setupProgress` is Mixed: the step set is open.
    setupEmail: { type: String, default: undefined },
    setupProgress: { type: Schema.Types.Mixed, default: undefined },
    // The CLI's optional `ref`, carried to the claiming user's `signup_source` (`attribution.server.ts`).
    signup_source: { type: String, default: undefined },
  },
  { timestamps: true }
);

export type KeyRegistrationDoc = NoNull<InferSchemaType<typeof KeyRegistrationSchema>>;

export default (models.KeyRegistration as Model<KeyRegistrationDoc>) ||
  mongoose.model<KeyRegistrationDoc>("KeyRegistration", KeyRegistrationSchema);

// The setup-funnel wire contract from `npx restless init`: an unverified lead `email` and a per-step
// `progress` map, both on `KeyRegistration`. Malformed values are dropped, never a reason to fail.

/**
 * The setup steps, in the order the CLI runs them. This is a KNOWN set for
 * the funnel ("how far did they get"), but not a CLOSED one on the wire:
 * the CLI ships to npm on its own cadence and may report a step this deploy
 * hasn't heard of, so `parseSetupStep` validates shape, not membership, and
 * an unrecognized step is stored opaquely. Only steps in THIS list count
 * toward "furthest reached".
 */
export const SETUP_STEPS = [
  "welcome",
  "generate_oas",
  "install_sdk",
  "test",
  "account",
] as const;

export type SetupStep = (typeof SETUP_STEPS)[number];

/** What happened to a step. A genuinely closed set - all three are ours. */
export const SETUP_STATUSES = ["started", "done", "failed"] as const;
export type SetupStatus = (typeof SETUP_STATUSES)[number];

/** Human labels for the known steps, for the admin funnel view. A step we
 *  don't recognize renders under its raw slug via `setupStepLabel`. */
export const SETUP_STEP_LABELS: Record<string, string> = {
  welcome: "Welcome",
  generate_oas: "Generate OAS",
  install_sdk: "Install SDK",
  test: "Test",
  account: "Account",
};

export function setupStepLabel(step: string): string {
  return SETUP_STEP_LABELS[step] ?? step;
}

/**
 * A storable step slug: lowercase alphanumeric plus dash/underscore (the
 * known steps use underscores, e.g. `generate_oas`), short enough to be a
 * name rather than a payload. Anything else is a client bug or an injection
 * attempt, not a step we haven't met. The shape guard also keeps the slug
 * safe to use as a dotted `$set` path key on the progress map.
 */
const STEP_SLUG = /^[a-z0-9][a-z0-9_-]{0,31}$/;

/**
 * Narrow an untrusted step from the wire to a storable slug, or
 * `undefined`. Shape check, not membership: an unknown step is kept
 * verbatim so a newer CLI's steps aren't silently dropped.
 */
export function parseSetupStep(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const v = value.trim().toLowerCase();
  return STEP_SLUG.test(v) ? v : undefined;
}

/** Narrow an untrusted status to one of the three we know, or `undefined`. */
export function parseSetupStatus(value: unknown): SetupStatus | undefined {
  if (typeof value !== "string") return undefined;
  const v = value.trim().toLowerCase();
  return (SETUP_STATUSES as readonly string[]).includes(v)
    ? (v as SetupStatus)
    : undefined;
}

/** The furthest step recorded with any status, by `SETUP_STEPS` order (a failed step was still reached).
 *  Derived on read, so an out-of-order progress call can never regress a stored "furthest". */
export function furthestKnownStep(steps: Iterable<string>): SetupStep | undefined {
  let best = -1;
  for (const step of steps) {
    const idx = (SETUP_STEPS as readonly string[]).indexOf(step);
    if (idx > best) best = idx;
  }
  return best >= 0 ? SETUP_STEPS[best] : undefined;
}

/**
 * A storable setup contact email, or `undefined`. Loose on purpose: it's an
 * unverified git-config value, so we validate a sane shape and cap the
 * length rather than trying to decide what a "real" address is. Lower-cased
 * and trimmed so the same person doesn't land as two leads.
 */
export function parseSetupEmail(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const v = value.trim().toLowerCase();
  if (v.length < 3 || v.length > 254) return undefined;
  // One `@`, something before it, and a dotted domain after. Deliberately
  // permissive - this is a lead, not an auth boundary.
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) return undefined;
  return v;
}
import { getServerSession } from "next-auth";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { authOptions } from "@/lib/auth";
import SignInScreen from "@/components/SignInScreen";
import dbConnect from "@/lib/mongoose";
import Project from "@/models/Project";
import type { ProjectDoc } from "@/models/Project";
import Invite from "@/models/Invite";
import DocsViewer from "@/models/DocsViewer";
import type { DocsViewerDoc } from "@/models/DocsViewer";
import { projectAccess } from "@/lib/projectAccess";
import { recordWaitlistSignup } from "@/lib/waitlist";

export const LAST_PROJECT_COOKIE = "restless_last_project";

/**
 * Smart root. Signed-out visitors get the sign-in button. Signed-in
 * users get bounced to whichever project they were last in - or, if
 * that cookie is missing/stale, to their most-recently-updated
 * project. Users with no projects but a pending invite fall through
 * to /projects so they can accept it. Users with no projects AND no
 * invites are sent to /get-started, which hands them `npx restless
 * init` (the command that creates their first project).
 */
export default async function Home() {
  const session = await getServerSession(authOptions);
  if (!session) {
    return <SignInScreen />;
  }

  await dbConnect();

  // Prefer the cookie if it still points at a project this user can
  // open. We validate access here so a hand-edited cookie or revoked
  // membership can't redirect into a 404.
  const jar = await cookies();
  const lastSlug = jar.get(LAST_PROJECT_COOKIE)?.value;
  if (lastSlug) {
    const exists = await Project.findOne(
      { slug: lastSlug, ...projectAccess(session.user.id) },
      "_id"
    ).lean();
    if (exists) redirect(`/api/${lastSlug}`);
  }

  // Fallback: most recently updated project the user has access to.
  // `updatedAt` isn't a perfect "last visited" signal, but for a
  // first-time landing (or after a cookie wipe) it's the best
  // heuristic we have without another data source.
  const recent = await Project.findOne(projectAccess(session.user.id), "slug")
    .sort({ updatedAt: -1 })
    .lean<Pick<ProjectDoc, "slug">>();
  if (recent?.slug) redirect(`/api/${recent.slug}`);

  // No projects. If they have a live invite, send them to /projects so
  // they can accept it (and see the "Add a new project" snippet).
  const email = session.user?.email?.toLowerCase();
  const hasInvite = email
    ? await Invite.exists({ email, expiresAt: { $gt: new Date() } })
    : false;
  if (hasInvite) redirect("/projects");

  // Docs VIEWERS are not dashboard users: an email with a viewer row (a
  // pending request or an approved grant on some project's request-access
  // docs) belongs on that project's docs, not on /get-started being handed
  // `npx restless init`. Bounce them there through the dashboard handoff,
  // which carries this session onto the docs host (NextAuth cookies never
  // cross to it). Most recently touched row wins when they have several.
  const viewerRow = email
    ? await DocsViewer.findOne({ email }, "projectId")
        .sort({ updatedAt: -1 })
        .lean<Pick<DocsViewerDoc, "projectId">>()
    : null;
  if (viewerRow?.projectId) {
    const viewerProject = await Project.findOne(
      { _id: viewerRow.projectId },
      "slug",
    ).lean<Pick<ProjectDoc, "slug">>();
    if (viewerProject?.slug) {
      redirect(`/api/docs-auth/from-dashboard?slug=${encodeURIComponent(viewerProject.slug)}`);
    }
  }

  // No projects and no invites: signup IS `npx restless init`, so send them to /get-started. The signup
  // row is best effort: a Mongo or Slack failure here must not 500 a brand new account's first page load.
  if (email) {
    try {
      await recordWaitlistSignup({
        email,
        source: "login",
        signupId: `login-${session.user.id}`,
      });
    } catch (err) {
      console.error(
        "[home] signup log failed:",
        err instanceof Error ? err.message : err,
      );
    }
  }
  redirect("/get-started");
}
