export default async function ProjectsPage() {
  const session = await getServerSession(authOptions);
  if (!session) redirect("/");

  await dbConnect();
  const projects = await Project.find(projectAccess(session.user.id)).sort({ name: 1 }).lean();

  // Pending invites for this signed-in email. The Invite TTL index
  // sweeps expired rows server-side, but we still filter on
  // expiresAt here so a brand-new expiry isn't surfaced before the
  // sweep runs. Joined to the project so we can show its name.
  const userEmail = session.user?.email?.toLowerCase();
  const inviteDocs = userEmail
    ? await Invite.find({
        email: userEmail,
        expiresAt: { $gt: new Date() },
      })
        .sort({ createdAt: -1 })
        .lean<Pick<InviteDoc, "projectId" | "token" | "invitedBy">[]>()
    : [];
  const inviteProjects = inviteDocs.length
    ? await Project.find(
        { _id: { $in: inviteDocs.map((i) => i.projectId) } },
        "name slug endpoints",
      ).lean<(Pick<ProjectDoc, "name" | "slug" | "endpoints"> & { _id: Types.ObjectId })[]>()
    : [];
  const projectById = new Map(
    inviteProjects.map((p) => [String(p._id), p]),
  );
  const invites = inviteDocs
    .map((i) => {
      const p = projectById.get(String(i.projectId));
      if (!p) return null;
      return {
        token: i.token,
        invitedBy: i.invitedBy,
        projectName: p.name,
        projectSlug: p.slug,
        endpoints: p.endpoints ?? 0,
      };
    })
    .filter((x): x is NonNullable<typeof x> => x !== null);

  // Most recent saved channel across all projects, used to drive
  // the sidebar's "Open Slack" deeplink. Newest wins so a freshly
  // created channel takes over from older ones automatically.
  type SavedChannel = { id: string; name: string; createdAt: Date };
  const allChannels = (
    projects as { slackChannels?: SavedChannel[] }[]
  ).flatMap((p) => p.slackChannels || []);
  const mostRecentChannel =
    allChannels.length > 0
      ? allChannels.sort(
          (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
        )[0]
      : null;

  return (
    <>
      <header className="flex items-center justify-between py-4">
        <img src="/restless.svg" alt="Restless" className="h-7" />
        <UserMenu
          email={session.user?.email ?? ""}
          isGod={isStaffEmail(session.user?.email)}
          direction="down"
        />
      </header>

      <div className="flex gap-14 py-8">
        <main className="flex-1 min-w-0">
          {invites.length > 0 && (
            <div className="mb-6">
              <h2 className="text-xs font-semibold text-sand-500 uppercase tracking-wider mb-2">
                Pending invites
              </h2>
              <ul className="divide-y divide-sand-200 border border-sand-200 rounded-md">
                {invites.map((inv) => (
                  <HomeInviteRow
                    key={inv.token}
                    token={inv.token}
                    projectName={inv.projectName}
                    invitedBy={inv.invitedBy}
                    endpoints={inv.endpoints}
                  />
                ))}
              </ul>
            </div>
          )}
          <div className="[&>.row:hover>.sep]:bg-transparent [&>.row:hover+.row>.sep]:bg-transparent">
            {projects.map((api, i) => (
              <div key={api.slug} className="row">
                {i > 0 && (
                  <div className="sep h-px bg-sand-200 transition-colors" />
                )}
                <div className="relative flex items-center justify-between py-4 -mx-3 px-3 rounded-lg hover:bg-sand-100 transition-colors">
                  <Link href={`/api/${api.slug}`} className="absolute inset-0 rounded-lg" />
                  <div>
                    <span className="text-sm font-medium text-sand-800">
                      {api.name}
                      {api.slug === "project-a0d1b5c7" && (
                        <span
                          title="Demo account"
                          aria-label="Demo account"
                          className="ml-1.5 inline-block align-middle text-[10px] font-semibold uppercase tracking-wide px-1.5 py-0.5 rounded bg-amber-100 text-amber-700"
                        >
                          DEMO
                        </span>
                      )}
                    </span>
                    <p className="text-xs text-sand-500">{api.endpoints} endpoints</p>
                  </div>
                  <div className="relative z-10 flex items-center gap-2">
                    <Link href={`/api/${api.slug}/users`} className="px-3 py-1 text-xs font-medium text-white bg-blue-600 rounded hover:bg-blue-700">
                      Users
                    </Link>
                    <Link href={`/api/${api.slug}/logs`} className="px-3 py-1 text-xs font-medium text-white bg-green-600 rounded hover:bg-green-700">
                      Logs
                    </Link>
                    <Link href={`/api/${api.slug}/docs`} className="px-3 py-1 text-xs font-medium text-sand-500 bg-sand-200 rounded hover:bg-sand-300">
                      Docs
                    </Link>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </main>

        <aside className="w-64 shrink-0 self-start">
          <h2 className="text-sm font-semibold text-sand-800 mb-1">Add a new project</h2>
          <p className="text-xs text-sand-500 mb-4">
