"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

export default function HomeInviteRow({
  token,
  projectName,
  invitedBy,
  endpoints,
}: {
  token: string;
  projectName: string;
  invitedBy: string;
  endpoints: number;
}) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function accept() {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/invites/${token}/accept`, { method: "POST" });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error || "Failed to accept invite");
        setLoading(false);
        return;
      }
      router.push(`/api/${data.slug}?welcome=1`);
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to accept invite");
      setLoading(false);
    }
  }

  return (
    <li className="flex items-center justify-between px-4 py-3 gap-3">
      <div className="min-w-0">
        <p className="text-sm font-medium text-sand-800 truncate">{projectName}</p>
        <p className="text-xs text-sand-500 truncate">
          Invited by {invitedBy}
          {endpoints ? ` · ${endpoints} endpoints` : ""}
        </p>
        {error && <p className="mt-1 text-xs text-red-600">{error}</p>}
      </div>
      <div className="shrink-0 flex items-center gap-2">
        <button
          onClick={accept}
          disabled={loading}
          className="px-3 py-1 text-xs font-medium text-white bg-sand-800 hover:bg-sand-900 disabled:opacity-50 cursor-pointer"
        >
          {loading ? "Joining..." : "Accept"}
        </button>
      </div>
    </li>
  );
}
