import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import dbConnect from "@/lib/mongoose";
import Project from "@/models/Project";
import type { ProjectDoc } from "@/models/Project";
import Invite from "@/models/Invite";
import Activity from "@/models/Activity";

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ token: string }> },
) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id || !session.user.email) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { token } = await params;

  await dbConnect();

  const invite = await Invite.findOne({ token });
  if (!invite || (invite.expiresAt && invite.expiresAt.getTime() < Date.now())) {
    if (invite) await Invite.deleteOne({ _id: invite._id });
    return NextResponse.json({ error: "Invite not found or expired" }, { status: 404 });
  }

  if (invite.email.toLowerCase() !== session.user.email.toLowerCase()) {
    return NextResponse.json(
      { error: `This invite is for ${invite.email}. Sign in with that account.` },
      { status: 403 },
    );
  }

  const userId = session.user.id;

  const update = await Project.updateOne(
    { _id: invite.projectId },
    { $addToSet: { members: userId } },
  );

  if (update.matchedCount === 0) {
    await Invite.deleteOne({ _id: invite._id });
    return NextResponse.json({ error: "Project no longer exists" }, { status: 404 });
  }

  const deleted = await Invite.deleteOne({ _id: invite._id });

  // Only log "Joined" once - the first caller actually adds them, and the
  // first deleteOne winning the race is the authoritative acceptance.
  if (update.modifiedCount > 0 && deleted.deletedCount > 0) {
    await Activity.create({
      project: invite.projectId,
      action: `Joined the project`,
      actor: session.user.email,
    });
  }

  const project = await Project.findById(invite.projectId, "slug").lean<Pick<ProjectDoc, "slug">>();
  return NextResponse.json({ slug: project?.slug });
}
