import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import dbConnect from "@/lib/mongoose";
import Invite from "@/models/Invite";

/**
 * Dismiss (decline) a pending invite. Same authorization shape as
 * accept: the signed-in email must match the invite's email, so a
 * stolen token can't be used to nuke someone else's invite. We just
 * delete the row - if the original inviter wants the user back in,
 * they can send a fresh invite.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ token: string }> },
) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.email) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { token } = await params;

  await dbConnect();

  const invite = await Invite.findOne({ token });
  if (!invite) return NextResponse.json({ ok: true });

  if (invite.email.toLowerCase() !== session.user.email.toLowerCase()) {
    return NextResponse.json(
      { error: `This invite is for ${invite.email}.` },
      { status: 403 },
    );
  }

  await Invite.deleteOne({ _id: invite._id });
  return NextResponse.json({ ok: true });
}
