/** Per-step setup funnel from `npx restless init`, landing on the durable `KeyRegistration` row (CLAUDE.md
 *  "Setup provenance"). Malformed is 400; a bad key or claimed project records nothing and still 200s. */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ projectId: string }> },
) {
  const { projectId } = await params;

  let body: {
    setup_key?: unknown;
    step?: unknown;
    status?: unknown;
    email?: unknown;
    setup_source?: unknown;
    setup_agent?: unknown;
  };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const setupKey =
    typeof body.setup_key === "string" && body.setup_key.trim()
      ? body.setup_key
      : null;
  if (!setupKey) {
    return NextResponse.json({ error: "Missing setup_key" }, { status: 400 });
  }

  const step = parseSetupStep(body.step);
  if (!step) {
    return NextResponse.json(
      { error: "Missing or invalid step" },
      { status: 400 },
    );
  }
  // Client currently only sends "done"; take a missing/unknown status as
  // "done" so a terse or future client still records the step as reached.
  const status = parseSetupStatus(body.status) ?? "done";
  const email = parseSetupEmail(body.email);
  const provenance = {
    setupSource: parseSetupSource(body.setup_source),
    setupAgent: parseSetupAgent(body.setup_agent),
  };

  await dbConnect();

  // Uniform quiet no-op for every "not our concern" case: bad/expired key,
  // or a project that's already been claimed (its setup key is spent). We
  // still return 200 - the client is fire-and-forget and ignores the body.
  const ignored = () => NextResponse.json({ ok: true });

  const proof = await verifySetupKey(projectId, setupKey);
  if (!proof.ok) return ignored();
  if (await Project.exists({ metricsId: projectId })) return ignored();

  const now = new Date();

  // One targeted `$set`. The step map is Mixed and the step slug is shape-
  // validated, so the dotted path is safe; `updateOne` without upsert means
  // a progress call for a projectId with no registration simply no-ops
  // (init is the only thing that may create a registration).
  const set: Record<string, unknown> = {
    [`setupProgress.steps.${step}`]: { status, at: now },
    "setupProgress.updatedAt": now,
  };
  if (email) set.setupEmail = email;

  // Provenance is backfill-only (the first init is the truth about how the
  // run started). It rarely arrives here, so only pay for the read when it
  // does; a filtered `$set` on each field would be an extra round-trip.
  if (provenance.setupSource || provenance.setupAgent) {
    const reg = (await KeyRegistration.findOne(
      { projectId },
      "setupSource setupAgent",
    ).lean()) as { setupSource?: string; setupAgent?: string } | null;
    if (provenance.setupSource && !reg?.setupSource) {
      set.setupSource = provenance.setupSource;
    }
    if (provenance.setupAgent && !reg?.setupAgent) {
      set.setupAgent = provenance.setupAgent;
    }
  }

  await KeyRegistration.updateOne({ projectId }, { $set: set });

  return NextResponse.json({ ok: true });
}
