import crypto, { timingSafeEqual } from "crypto";

import SetupCredential from "@/models/SetupCredential";
import type { SetupCredentialDoc } from "@/models/SetupCredential";

// Possession proof for the pre-claim `setupKey`: sha256 and constant-time compare against
// `SetupCredential.setupKeyHash`. Callers answer every failure identically; see CLAUDE.md, "CLI write surfaces".

export type SetupKeyOutcome =
  /** `setupKeyHash` is handed back because callers persist it: the staging
   *  rows key on it, and claim matches against it. */
  | { ok: true; setupKeyHash: string }
  | { ok: false };

export async function verifySetupKey(
  projectId: string,
  setupKey: string,
): Promise<SetupKeyOutcome> {
  const cred = await SetupCredential.findOne({ projectId }).lean<Pick<SetupCredentialDoc, "setupKeyHash" | "expiresAt"> | null>();
  if (!cred) return { ok: false };
  if (cred.expiresAt.getTime() < Date.now()) return { ok: false };

  const setupKeyHash = crypto
    .createHash("sha256")
    .update(setupKey)
    .digest("hex");
  const incoming = Buffer.from(setupKeyHash, "hex");
  const stored = Buffer.from(cred.setupKeyHash, "hex");
  // Length guard first: `timingSafeEqual` throws on a mismatch, and a stored
  // hash of the wrong width (truncated row, format change) would otherwise be
  // a 500 rather than a rejection.
  if (incoming.length !== stored.length) return { ok: false };
  if (!timingSafeEqual(incoming, stored)) return { ok: false };

  return { ok: true, setupKeyHash };
}

