import crypto from "crypto";

import { registerProject } from "@/lib/metrics";
import SetupCredential from "@/models/SetupCredential";

export const SETUP_KEY_TTL_HOURS = 6;

export function mintSetupCredential() {
  const setupKey = crypto.randomBytes(32).toString("hex");
  const setupKeyHash = crypto.createHash("sha256").update(setupKey).digest("hex");
  const expiresDate = new Date(Date.now() + SETUP_KEY_TTL_HOURS * 60 * 60 * 1000);
  const setupKeyExpiresAt = expiresDate
    .toISOString()
    .replace("T", " ")
    .replace(/\.\d{3}Z$/, "");
  return { setupKey, setupKeyHash, expiresDate, setupKeyExpiresAt };
}

/** A fresh setup key for an existing unclaimed project. Metrics replaces its row per project_id with
 *  `claimed: false`, so never call this for a project that may already be claimed. */
export async function renewSetupCredential(projectId: string, writeKeyHash: string) {
  const fresh = mintSetupCredential();
  await registerProject(projectId, {
    writeKeyHash,
    setupKeyHash: fresh.setupKeyHash,
    setupKeyExpiresAt: fresh.setupKeyExpiresAt,
  });
  await SetupCredential.findOneAndUpdate(
    { projectId },
    { setupKeyHash: fresh.setupKeyHash, expiresAt: fresh.expiresDate },
    { upsert: true },
  );
  return fresh;
}

