import { announceIfFirstProject, completeProjectClaim, type ClaimResult } from "@/lib/claimFlow";
import { renewSetupCredential } from "@/lib/setupCredential";
import type { SetupAgent } from "@/lib/setupProvenance";
import KeyRegistration from "@/models/KeyRegistration";
import PendingOAS from "@/models/PendingOAS";
import PendingSettings from "@/models/PendingSettings";
import Project from "@/models/Project";
import SetupCredential from "@/models/SetupCredential";
import SetupToken from "@/models/SetupToken";

// An unclaimed project whose setup run gave this email (`KeyRegistration.setupEmail`). The email is
// unverified, so a waiting project is only ever offered: the signed-in owner of that address confirms it.

export type WaitingProject = {
  projectId: string;
  name: string;
  setupAgent?: SetupAgent;
  createdAt: Date;
};

export type WaitingClaimResult = ClaimResult | { ok: false; reason: "not_found" };

const MAX_WAITING = 20;
// A live key this close to expiry is renewed instead, so metrics can't refuse the claim as expired.
const MIN_KEY_LIFE_MS = 5 * 60 * 1000;
// SetupToken requires a key, but this path never holds the plaintext, and the row is complete on write.
const EMAIL_CLAIM_SETUP_KEY = "claimed-by-email";

export async function findWaitingProjects(email: string): Promise<WaitingProject[]> {
  const regs = await KeyRegistration.find(
    { setupEmail: email.toLowerCase() },
    "projectId setupAgent createdAt",
  )
    .sort({ createdAt: -1 })
    .limit(MAX_WAITING)
    .lean<{ projectId: string; setupAgent?: SetupAgent; createdAt: Date }[]>();
  if (!regs.length) return [];

  const ids = regs.map((r) => r.projectId);
  const [claimed, specs] = await Promise.all([
    Project.find({ metricsId: { $in: ids } }, "metricsId").lean<{ metricsId: string }[]>(),
    PendingOAS.find({ projectId: { $in: ids } }, "projectId oas.info.title").lean<
      { projectId: string; oas?: { info?: { title?: unknown } } }[]
    >(),
  ]);
  const claimedIds = new Set(claimed.map((p) => p.metricsId));
  const titles = new Map(specs.map((s) => [s.projectId, s.oas?.info?.title]));

  return regs
    .filter((r) => !claimedIds.has(r.projectId))
    .map((r) => {
      const title = titles.get(r.projectId);
      return {
        projectId: r.projectId,
        name: typeof title === "string" && title.trim() ? title.trim() : "My API",
        ...(r.setupAgent ? { setupAgent: r.setupAgent } : {}),
        createdAt: r.createdAt,
      };
    });
}

export async function hasWaitingProjects(email: string): Promise<boolean> {
  return (await findWaitingProjects(email)).length > 0;
}

/** The hash to claim with: the live key's when it has time left, else a renewed one. Renewal is only
 *  safe because nothing else can claim with an expired key (metrics rewrites the row as unclaimed). */
async function claimableSetupKeyHash(projectId: string, writeKeyHash: string): Promise<string> {
  const cred = await SetupCredential.findOne({ projectId }, "setupKeyHash expiresAt").lean<
    { setupKeyHash: string; expiresAt: Date } | null
  >();
  if (cred && cred.expiresAt.getTime() - Date.now() > MIN_KEY_LIFE_MS) return cred.setupKeyHash;
  return (await renewSetupCredential(projectId, writeKeyHash)).setupKeyHash;
}

export async function claimWaitingProject({
  projectId,
  userId,
  userEmail,
}: {
  projectId: string;
  userId: string;
  userEmail: string;
}): Promise<WaitingClaimResult> {
  const reg = await KeyRegistration.findOne(
    { projectId, setupEmail: userEmail.toLowerCase() },
    "writeKeyHash",
  ).lean<{ writeKeyHash: string } | null>();
  if (!reg) return { ok: false, reason: "not_found" };
  if (await Project.exists({ metricsId: projectId })) return { ok: false, reason: "already_claimed" };

  const setupKeyHash = await claimableSetupKeyHash(projectId, reg.writeKeyHash);
  // Claim attaches staged rows by key hash, and these may predate the key in use (a lost link, a re-run).
  await Promise.all([
    PendingOAS.updateOne({ projectId }, { $set: { setupKeyHash } }),
    PendingSettings.updateOne({ projectId }, { $set: { setupKeyHash } }),
  ]);

  const result = await completeProjectClaim({ projectId, setupKeyHash, userId, userEmail });
  if (!result.ok) return result;

  // Completing the link's SetupToken stops a still-polling CLI waiting forever; it's also the signup record.
  try {
    const marked = await SetupToken.updateMany(
      { projectId, status: "pending" },
      { $set: { status: "complete", email: userEmail, slug: result.slug } },
    );
    if (!marked.modifiedCount) {
      await SetupToken.create({
        token: crypto.randomUUID().replace(/-/g, ""),
        projectId,
        setupKey: EMAIL_CLAIM_SETUP_KEY,
        status: "complete",
        email: userEmail,
        slug: result.slug,
      });
    }
  } catch (err) {
    console.error("[waiting-claim] signup record failed:", err instanceof Error ? err.message : err);
  }
  await announceIfFirstProject(userId, userEmail);

  return result;
}

