import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";

import { authOptions } from "@/lib/auth";
import dbConnect from "@/lib/mongoose";
import { projectAccess } from "@/lib/projectAccess";
import { claimWaitingProject } from "@/lib/waitingProjects";
import Project from "@/models/Project";

/** "Add to my account" on a project waiting under the signed-in email. The session email is
 *  provider-verified, and that match is the whole authorization. */
export async function POST(
  _req: NextRequest,
  { params }: { params: Promise<{ projectId: string }> },
) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id || !session.user.email) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const { projectId } = await params;
  const userId = session.user.id;

  await dbConnect();

  const result = await claimWaitingProject({ projectId, userId, userEmail: session.user.email });
  if (result.ok) return NextResponse.json({ slug: result.slug });

  if (result.reason === "already_claimed") {
    // A double click, or the claim link winning the race: already theirs is the success they wanted.
    const own = await Project.findOne({ metricsId: projectId, ...projectAccess(userId) }, "slug")
      .lean<{ slug: string } | null>();
    if (own) return NextResponse.json({ slug: own.slug });
    return NextResponse.json({ error: "This project has already been claimed." }, { status: 409 });
  }
  if (result.reason === "not_found") {
    return NextResponse.json({ error: "Project not found" }, { status: 404 });
  }
  return NextResponse.json(
    { error: "Could not add this project. Please try again." },
    { status: result.reason === "expired" ? 410 : 502 },
  );
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";

import { authOptions } from "@/lib/auth";
import dbConnect from "@/lib/mongoose";
import { dismissWaitingProject } from "@/lib/waitingProjects";

/** "Not mine": stop offering this project to the signed-in email. Only that email's own offer is
 *  touched, so it can't hide a project waiting for anyone else. */
export async function POST(
  _req: NextRequest,
  { params }: { params: Promise<{ projectId: string }> },
) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.email) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const { projectId } = await params;

  await dbConnect();
  await dismissWaitingProject(projectId, session.user.email);
  return NextResponse.json({ ok: true });
}

