/**
 * GitHub login, wrapping the built-in provider but overriding `userinfo` so
 * the email is always resolved from `/user/emails` and REQUIRED to be
 * verified (see `pickVerifiedGithubEmail`). Everything else (scopes, the
 * `profile` mapper) comes from the built-in provider.
 */
export const githubProvider = GithubProvider({
  clientId: process.env.GITHUB_CLIENT_ID!,
  clientSecret: process.env.GITHUB_CLIENT_SECRET!,
  // GitHub sends an RFC 9207 `iss` on the callback since April 2026; openid-client refuses
  // the callback unless the configured issuer matches it exactly. Not set by next-auth v4.
  issuer: "https://github.com/login/oauth",
  allowDangerousEmailAccountLinking: true,
  userinfo: {
    url: "https://api.github.com/user",
    async request({ tokens }) {
      const headers = {
        Authorization: `Bearer ${tokens.access_token}`,
        // GitHub's API refuses requests without a User-Agent.
        "User-Agent": "restless-app",
        Accept: "application/vnd.github+json",
      };
