"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

export default function HomeWaitingRow({
  projectId,
  projectName,
  setupBy,
  setupAt,
}: {
  projectId: string;
  projectName: string;
  setupBy: string | null;
  setupAt: string;
}) {
  const router = useRouter();
  const [busy, setBusy] = useState<"claim" | "dismiss" | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function act(action: "claim" | "dismiss") {
    setBusy(action);
    setError(null);
    try {
      const res = await fetch(`/api/projects/waiting/${projectId}/${action}`, { method: "POST" });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error || "Something went wrong");
        setBusy(null);
        return;
      }
      if (action === "claim") router.push(`/api/${data.slug}?welcome=1`);
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
      setBusy(null);
    }
  }

  return (
    <li className="flex items-center justify-between px-4 py-3 gap-3">
      <div className="min-w-0">
        <p className="text-sm font-medium text-sand-800 truncate">{projectName}</p>
        <p className="text-xs text-sand-500 truncate">
          Set up {setupBy ? `with ${setupBy} ` : ""}on {setupAt} using your email
        </p>
        {error && <p className="mt-1 text-xs text-red-600">{error}</p>}
      </div>
      <div className="shrink-0 flex items-center gap-2">
        <button
          onClick={() => act("dismiss")}
          disabled={busy !== null}
          className="px-3 py-1 text-xs font-medium text-sand-600 bg-sand-200 hover:bg-sand-300 disabled:opacity-50 cursor-pointer"
        >
          {busy === "dismiss" ? "Removing..." : "Not mine"}
        </button>
        <button
          onClick={() => act("claim")}
          disabled={busy !== null}
          className="px-3 py-1 text-xs font-medium text-white bg-sand-800 hover:bg-sand-900 disabled:opacity-50 cursor-pointer"
        >
          {busy === "claim" ? "Adding..." : "Add to my account"}
        </button>
      </div>
    </li>
  );
}

