import { announceIfFirstProject, completeProjectClaim } from "@/lib/claimFlow";
import { renewSetupCredential } from "@/lib/setupCredential";
import KeyRegistration from "@/models/KeyRegistration";
import PendingOAS from "@/models/PendingOAS";
import PendingSettings from "@/models/PendingSettings";
import Project from "@/models/Project";
import SetupCredential from "@/models/SetupCredential";
import SetupToken from "@/models/SetupToken";
import {
  claimWaitingProject,
  dismissWaitingProject,
  findWaitingProjects,
} from "@/lib/waitingProjects";

type Mock = ReturnType<typeof vi.fn>;
const m = (fn: unknown) => fn as Mock;
const lean = (value: unknown) => ({ lean: () => Promise.resolve(value) });

const USER = { userId: "u1", userEmail: "Dev@Example.com" };
const PROJECT_ID = "11111111-2222-3333-4444-555555555555";

beforeEach(() => {
  vi.clearAllMocks();
  m(completeProjectClaim).mockResolvedValue({ ok: true, slug: "project-11111111" });
  m(KeyRegistration.findOne).mockReturnValue(lean({ writeKeyHash: "wk" }));
  m(Project.exists).mockResolvedValue(null);
  m(SetupCredential.findOne).mockReturnValue(
    lean({ setupKeyHash: "live", expiresAt: new Date(Date.now() + 60 * 60 * 1000) }),
  );
  m(renewSetupCredential).mockResolvedValue({ setupKeyHash: "renewed" });
  m(SetupToken.updateMany).mockResolvedValue({ modifiedCount: 1 });
});

describe("findWaitingProjects", () => {
  function registrations(rows: unknown[]) {
    m(KeyRegistration.find).mockReturnValue({
      sort: () => ({ limit: () => lean(rows) }),
    });
  }

  it("lists unclaimed registrations under the lower-cased email, named from the staged spec", async () => {
    const at = new Date("2026-10-01T00:00:00Z");
    registrations([
      { projectId: "a", setupAgent: "claude", createdAt: at },
      { projectId: "b", createdAt: at },
      { projectId: "c", createdAt: at },
    ]);
    m(Project.find).mockReturnValue(lean([{ metricsId: "b" }]));
    m(PendingOAS.find).mockReturnValue(lean([{ projectId: "a", oas: { info: { title: " Pets API " } } }]));

    const waiting = await findWaitingProjects("Dev@Example.com");

    expect(m(KeyRegistration.find).mock.calls[0][0]).toEqual({ setupEmail: "dev@example.com" });
    expect(waiting).toEqual([
      { projectId: "a", name: "Pets API", setupAgent: "claude", createdAt: at },
      { projectId: "c", name: "My API", createdAt: at },
    ]);
  });

  it("skips the joins when nothing is registered under the email", async () => {
    registrations([]);
    expect(await findWaitingProjects("dev@example.com")).toEqual([]);
    expect(Project.find).not.toHaveBeenCalled();
  });
});

describe("claimWaitingProject", () => {
  it("claims with the live key, moving staged rows onto it first", async () => {
    const result = await claimWaitingProject({ projectId: PROJECT_ID, ...USER });

    expect(result).toEqual({ ok: true, slug: "project-11111111" });
    expect(m(KeyRegistration.findOne).mock.calls[0][0]).toEqual({
      projectId: PROJECT_ID,
      setupEmail: "dev@example.com",
    });
    expect(renewSetupCredential).not.toHaveBeenCalled();
    expect(PendingOAS.updateOne).toHaveBeenCalledWith(
      { projectId: PROJECT_ID },
      { $set: { setupKeyHash: "live" } },
    );
    expect(PendingSettings.updateOne).toHaveBeenCalledWith(
      { projectId: PROJECT_ID },
      { $set: { setupKeyHash: "live" } },
    );
    expect(completeProjectClaim).toHaveBeenCalledWith({
      projectId: PROJECT_ID,
      setupKeyHash: "live",
      ...USER,
    });
    expect(announceIfFirstProject).toHaveBeenCalledWith("u1", "Dev@Example.com");
  });

  it.each([
    ["expired", { setupKeyHash: "old", expiresAt: new Date(Date.now() - 1000) }],
    ["about to expire", { setupKeyHash: "old", expiresAt: new Date(Date.now() + 60 * 1000) }],
    ["gone", null],
  ])("renews the setup key when the live one is %s", async (_label, cred) => {
    m(SetupCredential.findOne).mockReturnValue(lean(cred));

    await claimWaitingProject({ projectId: PROJECT_ID, ...USER });

    expect(renewSetupCredential).toHaveBeenCalledWith(PROJECT_ID, "wk");
    expect(completeProjectClaim).toHaveBeenCalledWith(
      expect.objectContaining({ setupKeyHash: "renewed" }),
    );
  });

  it("refuses a project not waiting under this email", async () => {
    m(KeyRegistration.findOne).mockReturnValue(lean(null));

    expect(await claimWaitingProject({ projectId: PROJECT_ID, ...USER })).toEqual({
      ok: false,
      reason: "not_found",
    });
    expect(completeProjectClaim).not.toHaveBeenCalled();
  });

  it("never renews a key for a project that is already claimed", async () => {
    m(Project.exists).mockResolvedValue({ _id: "p" });
    m(SetupCredential.findOne).mockReturnValue(lean(null));

    expect(await claimWaitingProject({ projectId: PROJECT_ID, ...USER })).toEqual({
      ok: false,
      reason: "already_claimed",
    });
    expect(renewSetupCredential).not.toHaveBeenCalled();
    expect(completeProjectClaim).not.toHaveBeenCalled();
  });

  it("completes the claim link's pending SetupToken", async () => {
    await claimWaitingProject({ projectId: PROJECT_ID, ...USER });

    expect(SetupToken.updateMany).toHaveBeenCalledWith(
      { projectId: PROJECT_ID, status: "pending" },
      { $set: { status: "complete", email: "Dev@Example.com", slug: "project-11111111" } },
    );
    expect(SetupToken.create).not.toHaveBeenCalled();
  });

  it("writes a completed SetupToken when the run never made a claim link", async () => {
    m(SetupToken.updateMany).mockResolvedValue({ modifiedCount: 0 });

    await claimWaitingProject({ projectId: PROJECT_ID, ...USER });

    expect(SetupToken.create).toHaveBeenCalledWith(
      expect.objectContaining({ projectId: PROJECT_ID, status: "complete", slug: "project-11111111" }),
    );
  });

  it("records nothing when the claim fails", async () => {
    m(completeProjectClaim).mockResolvedValue({ ok: false, reason: "failed" });

    expect(await claimWaitingProject({ projectId: PROJECT_ID, ...USER })).toEqual({
      ok: false,
      reason: "failed",
    });
    expect(SetupToken.updateMany).not.toHaveBeenCalled();
    expect(announceIfFirstProject).not.toHaveBeenCalled();
  });
});

describe("dismissWaitingProject", () => {
  it("forgets the email only on this email's own offer", async () => {
    await dismissWaitingProject(PROJECT_ID, "Dev@Example.com");

    expect(KeyRegistration.updateOne).toHaveBeenCalledWith(
      { projectId: PROJECT_ID, setupEmail: "dev@example.com" },
      { $unset: { setupEmail: "" } },
    );
  });
});

