import KeyRegistration from "@/models/KeyRegistration";
import { withSetupLock } from "@/lib/setupCredential";

const updateOne = KeyRegistration.updateOne as unknown as ReturnType<typeof vi.fn>;
const exists = KeyRegistration.exists as unknown as ReturnType<typeof vi.fn>;

beforeEach(() => {
  vi.clearAllMocks();
  updateOne.mockResolvedValue({ matchedCount: 1 });
  exists.mockResolvedValue({ _id: "r" });
});

describe("withSetupLock", () => {
  it("takes the lock only on a never-claimed registration with no live lock", async () => {
    const fn = vi.fn(async () => "ran");

    expect(await withSetupLock("p1", fn)).toBe("ran");

    const [filter, update] = updateOne.mock.calls[0];
    expect(filter).toMatchObject({ projectId: "p1", claimedAt: { $exists: false } });
    expect(filter.$or).toEqual([
      { setupLockUntil: { $exists: false } },
      { setupLockUntil: { $lte: expect.any(Date) } },
    ]);
    expect(update.$set.setupLockUntil.getTime()).toBeGreaterThan(Date.now());
  });

  it("releases only its own lock, even when the work throws", async () => {
    await expect(
      withSetupLock("p1", async () => {
        throw new Error("boom");
      }),
    ).rejects.toThrow("boom");

    const token = updateOne.mock.calls[0][1].$set.setupLockToken;
    expect(updateOne.mock.calls[1]).toEqual([
      { projectId: "p1", setupLockToken: token },
      { $unset: { setupLockToken: "", setupLockUntil: "" } },
    ]);
  });

  it("refuses when the project was claimed or the lock is held", async () => {
    updateOne.mockResolvedValueOnce({ matchedCount: 0 });
    const fn = vi.fn();

    expect(await withSetupLock("p1", fn)).toBeNull();
    expect(fn).not.toHaveBeenCalled();
  });

  it("runs unlocked when there is no registration to lock", async () => {
    updateOne.mockResolvedValueOnce({ matchedCount: 0 });
    exists.mockResolvedValue(null);

    expect(await withSetupLock("p1", async () => "ran")).toBe("ran");
  });
});

