    }
  } catch (err) {
    const msg = `Couldn't prepare the login link (${err.message}).`;
    debug.log('error', { headline: msg });
    if (asJson) console.log(JSON.stringify({ ok: false, error: msg }, null, 2));
    else console.log(red(`\n  ✗ ${msg}\n`));
    await debug.flushAndExit(1);
  }

